CREATE TABLE buildings (id text PRIMARY KEY, legacy_bitrix_id text UNIQUE, name text NOT NULL, address text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
CREATE TABLE floors (id text PRIMARY KEY, legacy_bitrix_id text UNIQUE, building_id text NOT NULL REFERENCES buildings, name text NOT NULL, number integer NOT NULL DEFAULT 0, background_svg text, legacy_bg_file_id text, width double precision NOT NULL DEFAULT 1200 CHECK(width>0), height double precision NOT NULL DEFAULT 800 CHECK(height>0), version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true);
CREATE TABLE space_types (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE rooms (id text PRIMARY KEY, legacy_bitrix_id text UNIQUE, floor_id text NOT NULL REFERENCES floors, name text NOT NULL, area_m2 numeric CHECK(area_m2>=0), shape jsonb NOT NULL, space_type_id text REFERENCES space_types, active boolean NOT NULL DEFAULT true, UNIQUE(id,floor_id));
CREATE TABLE furniture_templates (id text PRIMARY KEY, legacy_bitrix_id text UNIQUE, name text NOT NULL, svg text, legacy_svg_file_id text, is_workplace boolean NOT NULL DEFAULT false, width double precision CHECK(width>0), depth double precision CHECK(depth>0));
CREATE TABLE furniture (id text PRIMARY KEY, legacy_bitrix_id text UNIQUE, floor_id text NOT NULL REFERENCES floors, room_id text, template_id text NOT NULL REFERENCES furniture_templates, inventory_number text, x double precision NOT NULL, y double precision NOT NULL, rotation double precision NOT NULL DEFAULT 0, width double precision CHECK(width>0), depth double precision CHECK(depth>0), geometry_verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, FOREIGN KEY(room_id,floor_id) REFERENCES rooms(id,floor_id));
CREATE INDEX furniture_floor ON furniture(floor_id);
CREATE TABLE workplaces (id text PRIMARY KEY, furniture_id text NOT NULL UNIQUE REFERENCES furniture, code text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','disabled')));
CREATE TABLE departments_projection (id text PRIMARY KEY, name text NOT NULL, parent_id text REFERENCES departments_projection, synced_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE employees_projection (id text PRIMARY KEY, bitrix_user_id text UNIQUE, display_name text NOT NULL, department_id text REFERENCES departments_projection, position text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, synced_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX employee_department ON employees_projection(department_id);
CREATE TABLE workplace_assignments (id text PRIMARY KEY, employee_id text NOT NULL REFERENCES employees_projection, workplace_id text NOT NULL REFERENCES workplaces, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, created_by text NOT NULL, CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE UNIQUE INDEX one_active_workplace ON workplace_assignments(workplace_id) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX one_active_employee ON workplace_assignments(employee_id) WHERE valid_to IS NULL;
CREATE TABLE cost_rates (id text PRIMARY KEY, space_type_id text NOT NULL REFERENCES space_types, building_id text REFERENCES buildings, room_id text REFERENCES rooms, rate_per_m2 numeric NOT NULL CHECK(rate_per_m2>=0), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), period text NOT NULL DEFAULT 'month' CHECK(period IN ('month','year')), valid_from date NOT NULL, valid_to date, CHECK(valid_to IS NULL OR valid_to>valid_from), CHECK(room_id IS NULL OR building_id IS NULL));
CREATE TABLE parking_spots (id text PRIMARY KEY, building_id text NOT NULL REFERENCES buildings, number text NOT NULL, area_m2 numeric CHECK(area_m2>=0), status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','disabled')), UNIQUE(building_id,number));
CREATE TABLE parking_assignments (id text PRIMARY KEY, parking_spot_id text NOT NULL REFERENCES parking_spots, employee_id text NOT NULL REFERENCES employees_projection, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, created_by text NOT NULL, CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE UNIQUE INDEX one_active_parking ON parking_assignments(parking_spot_id) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX one_active_employee_parking ON parking_assignments(employee_id) WHERE valid_to IS NULL;
CREATE TABLE layout_versions (id text PRIMARY KEY, floor_id text NOT NULL REFERENCES floors, version integer NOT NULL, snapshot jsonb NOT NULL, comment text NOT NULL DEFAULT '', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(floor_id,version));
CREATE TABLE audit_log (id text PRIMARY KEY, actor_id text NOT NULL, action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_runs (id text PRIMARY KEY, source_hash text NOT NULL UNIQUE, report jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE migration_quarantine (id text PRIMARY KEY, run_id text NOT NULL REFERENCES import_runs, source_id text NOT NULL, reason text NOT NULL, payload jsonb NOT NULL);
